CREATE OR REPLACE FUNCTION public.validated_storage_object(_bucket text, _path text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public AS $$ SELECT CASE _bucket WHEN 'talent-private-documents' THEN EXISTS(SELECT 1 FROM public.talent_private_documents d WHERE d.storage_path=_path AND d.validated_at IS NOT NULL AND NOT d.download_only AND d.user_id::text=split_part(_path,'/',1)) WHEN 'talent-documents' THEN EXISTS(SELECT 1 FROM public.talent_shared_documents d WHERE d.storage_path=_path AND d.validated_at IS NOT NULL AND d.deleted_at IS NULL) OR EXISTS(SELECT 1 FROM public.talent_shared_document_versions v JOIN public.talent_shared_documents d ON d.id=v.document_id WHERE v.storage_path=_path AND v.validated_at IS NOT NULL AND d.deleted_at IS NULL) WHEN 'talent-invite-docs' THEN EXISTS(SELECT 1 FROM public.talent_invitation_documents d WHERE d.storage_path=_path AND d.validated_at IS NOT NULL) WHEN 'agency-compliance-docs' THEN EXISTS(SELECT 1 FROM public.agency_compliance_documents d WHERE d.storage_path=_path AND d.validated_at IS NOT NULL) ELSE true END; $$;
REVOKE ALL ON FUNCTION public.validated_storage_object(text,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.validated_storage_object(text,text) TO authenticated,service_role;